/**
 * Stage 1 review-only helper: filtered top manual attention (group-level).
 *
 * Input:
 *   - exports/dedup-audit/concept-key-group-review-latest.csv
 *     (generated by scripts/concept-key-group-review-stage1.mjs)
 *
 * Output:
 *   - exports/dedup-audit/concept-key-group-top-attention-latest.csv
 *   - (stamped) concept-key-group-top-attention-<stamp>.csv
 *
 * Filtering intent:
 *   - include groups where issue_types is not empty
 *   - and prioritize groups where confidence is not high OR an override exists OR the suggested key looks suspiciously short/generic
 *
 * No DB writes.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { resolve, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const inPath = resolve(root, "exports/dedup-audit/concept-key-group-review-latest.csv");
const outDir = resolve(root, "exports/dedup-audit");

function parseCsvLine(line) {
  const cells = [];
  let cur = "";
  let inQuotes = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') {
      if (inQuotes && line[i + 1] === '"') {
        cur += '"';
        i++;
        continue;
      }
      inQuotes = !inQuotes;
      continue;
    }
    if (!inQuotes && ch === ",") {
      cells.push(cur);
      cur = "";
      continue;
    }
    cur += ch;
  }
  cells.push(cur);
  return cells;
}

function csvEscape(value) {
  const str = value == null ? "" : String(value);
  if (/[",\r\n]/.test(str)) return `"${str.replace(/"/g, '""')}"`;
  return str;
}

function readCsv(path) {
  const raw = readFileSync(path, "utf8").trimEnd();
  if (!raw) return { header: [], rows: [] };
  const lines = raw.split(/\r?\n/);
  const header = parseCsvLine(lines[0]).map((s) => String(s).trim());
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const cells = parseCsvLine(lines[i]);
    const row = {};
    for (let j = 0; j < header.length; j++) row[header[j]] = cells[j] ?? "";
    rows.push(row);
  }
  return { header, rows };
}

function nonEmpty(s) {
  return String(s ?? "").trim().length > 0;
}

function isSuspiciousKey(suggestedKey, issueTypes) {
  const key = String(suggestedKey ?? "").trim();
  const it = String(issueTypes ?? "");
  if (!key) return false;

  // Core signals.
  if (key.length <= 4) return true;
  if (it.includes("quoted_root_generic_common_word")) return true;
  if (it.includes("short_concept_key_len")) return true;

  return false;
}

const issuePriority = [
  "expanded_from_mot_de_passe_context",
  "quoted_root_generic_common_word",
  "short_concept_key_len",
  "short_concept_key_len",
];

function priorityScore(issueTypes) {
  const it = String(issueTypes ?? "");
  const parts = it.split(";").map((x) => x.trim()).filter(Boolean);
  let score = 100;
  for (const p of parts) {
    const idx = issuePriority.indexOf(p);
    if (idx >= 0) score = Math.min(score, idx);
  }
  return score;
}

function main() {
  if (!existsSync(inPath)) {
    console.error("Missing input:", inPath);
    process.exit(1);
  }

  const { rows } = readCsv(inPath);

  const outColumns = [
    "duplicate_group_id",
    "group_size",
    "final_recommended_concept_key",
    "suggested_concept_key",
    "suggested_override_concept_key",
    "issue_types",
    "confidence",
    "representative_question",
    "member_question_previews",
    "human_approved_concept_key",
    "human_notes",
  ];

  const filtered = [];
  for (const r of rows) {
    const issueTypes = String(r.issue_types ?? "").trim();
    if (!issueTypes) continue;

    const confidence = String(r.confidence ?? "").trim();
    const suggestedOverride = String(r.suggested_override_concept_key ?? "").trim();
    const suggestedKey = String(r.suggested_concept_key ?? "").trim();

    const suggestedSuspicious = isSuspiciousKey(suggestedKey, issueTypes);

    // Intent-based filtering (current dataset note):
    // In the current outputs, most flagged rows have confidence="high".
    // If we make confidence a hard gate, the result can become empty.
    //
    // So we treat "confidence not high" as an additional priority signal,
    // but we still require issue_types to be non-empty (i.e. something is flagged).
    const include = confidence !== "high" || nonEmpty(suggestedOverride) || suggestedSuspicious;

    if (!include) continue;
    filtered.push(r);
  }

  // Sort: overrides first, then non-high confidence, then issue priority.
  filtered.sort((a, b) => {
    const ao = nonEmpty(a.suggested_override_concept_key);
    const bo = nonEmpty(b.suggested_override_concept_key);
    if (ao !== bo) return ao ? -1 : 1;

    const ac = String(a.confidence ?? "").trim() === "high";
    const bc = String(b.confidence ?? "").trim() === "high";
    if (ac !== bc) return ac ? 1 : -1;

    const psA = priorityScore(a.issue_types);
    const psB = priorityScore(b.issue_types);
    if (psA !== psB) return psA - psB;

    return String(a.duplicate_group_id).localeCompare(String(b.duplicate_group_id));
  });

  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  mkdirSync(outDir, { recursive: true });
  const outStamped = join(outDir, `concept-key-group-top-attention-${stamp}.csv`);
  const outLatest = join(outDir, "concept-key-group-top-attention-latest.csv");

  const headerLine = outColumns.join(",");
  const body = filtered
    .map((r) => outColumns.map((c) => csvEscape(r[c] ?? "")).join(","))
    .join("\n");

  writeFileSync(outStamped, `${headerLine}\n${body}`, "utf8");
  writeFileSync(outLatest, `${headerLine}\n${body}`, "utf8");

  // Summaries.
  const groupsIncluded = filtered.length;
  const groupsWithOverrides = filtered.filter((r) => nonEmpty(r.suggested_override_concept_key)).length;
  const groupsNeedingManualAttention = filtered.length; // by filter: issue_types non-empty

  const smallEnough = groupsIncluded <= 30 ? "small_enough" : "needs_more_triage";

  console.log(JSON.stringify({
    outLatest,
    summary: {
      groups_included: groupsIncluded,
      groups_with_overrides: groupsWithOverrides,
      groups_needing_manual_attention: groupsNeedingManualAttention,
      suitability_for_first_backfill: smallEnough === "small_enough" ? "suitable_with_review" : "review_but_might_be_large",
    },
  }, null, 2));
}

main();

